const output = JSON.parse($input.first().json.stdout);
return [{
  json: output
}];

// Get the items from the previous node (the Google Search output)
const searchResults = $input.first().json.feed

// Check if search results exist
if (!searchResults) {
  // If no results, return a message to the AI
  return [{
    json: {
      cleaned_news_data: "No recent news found for this company."
    }
  }];
}

const searchResultsTen = searchResults.slice(0, 5);

// Process the search results to create a clean text format
const cleanedNewsData = searchResultsTen.map(result => {
  // Extract the title, link, and snippet
  const title = result.title;
  const link = result.url;
  const summary = result.summary;
  const sent_val = result.overall_sentiment_label;

  // Format into a readable string
  return `Title: ${title}\nLink: ${link}\nSummary: ${summary}\nOverall Sentiment: ${sent_val}\n`;
}).join(''); // Join all results into a single string

// Return the cleaned data as a new JSON property
return [{
  json: {
    cleaned_news_data: cleanedNewsData
  }
}];

// Assuming your text is coming from the previous node as 'content'
const inputText = $input.first().json.content.parts[0].text

// A simple way to handle potential markdown issues is to replace the characters
const safeText = inputText
  .replace(/\*/g, '\\*')  // Escape asterisks
  .replace(/_/g, '\\_')  // Escape underscores
  .replace(/\[/g, '\\[')  // Escape brackets
  .replace(/`/g, '\\`');  // Escape backticks

// Or, if you want to remove them altogether
// const safeText = inputText.replace(/[*_`]/g, '');

return {
  json: {
    safeText: safeText
  }
};
